-- KS Campfire Chat: each visible /say is from a real, player-clicked button.
-- No text is generated by an AI or obtained from other players. No timed chat.
KSCampfireChat=KSCampfireChat or {}
local A=KSCampfireChat
A.CAMPFIRE_SPELL_ID=1283391
A.CAMPFIRE_BUFF="Campfire Nearby"
A.CHAT_COOLDOWN=8
A.bags=A.bags or {}
A.lastChoice=A.lastChoice or {}

local function matchesAura(aura)
  if type(aura)~="table" then return false end
  local ok,matched=pcall(function()
    return aura.spellId==A.CAMPFIRE_SPELL_ID or aura.name==A.CAMPFIRE_BUFF
  end)
  return ok and matched or false
end

function A:CampfireNearby()
  -- Prefer the exact Forever aura ID; feature-detect supported modern API.
  if C_UnitAuras and type(C_UnitAuras.GetPlayerAuraBySpellID)=="function" then
    local ok,aura=pcall(C_UnitAuras.GetPlayerAuraBySpellID,self.CAMPFIRE_SPELL_ID)
    if ok and aura then return true end
  end
  if C_UnitAuras and type(C_UnitAuras.GetAuraDataByIndex)=="function" then
    for i=1,60 do
      local ok,aura=pcall(C_UnitAuras.GetAuraDataByIndex,"player",i,"HELPFUL")
      if not ok then break end
      if not aura then break end
      if matchesAura(aura) then return true end
    end
  end
  -- Classic/Forever-compatible fallback. Ignore malformed/secret aura fields
  -- and fail CLOSED if no available API confirms the exact buff.
  for _,fn in ipairs({UnitBuff,UnitAura}) do
    if type(fn)=="function" then
      for i=1,60 do
        local ok,name,id=pcall(function()
          local auraName,_,_,_,_,_,_,_,_,spellID=fn("player",i)
          return auraName,spellID
        end)
        if not ok then break end
        if name==nil then break end
        local safe,match=pcall(function()
          return name==self.CAMPFIRE_BUFF or id==self.CAMPFIRE_SPELL_ID
        end)
        if safe and match then return true end
      end
    end
  end
  return false
end

-- Draw without replacement until a category has exhausted its pool.
function A:Pick(category)
  local lines=self.lines and self.lines[category]
  if type(lines)~="table" or #lines==0 then return nil end
  local bag=self.bags[category]
  if type(bag)~="table" or #bag==0 then
    bag={}
    for i=1,#lines do bag[i]=i end
    for i=#bag,2,-1 do
      local j=math.random(i)
      bag[i],bag[j]=bag[j],bag[i]
    end
    if #bag>1 and bag[#bag]==self.lastChoice[category] then
      bag[1],bag[#bag]=bag[#bag],bag[1]
    end
    self.bags[category]=bag
  end
  local index=table.remove(bag)
  self.lastChoice[category]=index
  return lines[index]
end

function A:Tell(category)
  local enabled=KoolSupport:IsModuleEnabled("ks_campfire_chat")
  if not enabled then return false,"Enable Campfire Chat in Modules first." end
  if not (self.lines and type(self.lines[category])=="table") then
    return false,"Unknown campfire story type."
  end
  if not self:CampfireNearby() then
    return false,"Get closer to a campfire. Campfire Nearby must be active."
  end
  local now
  if type(GetTime)=="function" then
    local ok,number=pcall(GetTime)
    if ok and type(number)=="number" and number==number then now=number end
  end
  if not now then return false,"Game clock unavailable; no chat sent." end
  if self.lastSent and now-self.lastSent<self.CHAT_COOLDOWN then
    return false,"Let the fire crackle a moment before another story."
  end
  local fn=SendChatMessage
  if type(fn)~="function" and C_ChatInfo then fn=C_ChatInfo.SendChatMessage end
  if type(fn)~="function" then
    return false,"Forever chat API unavailable. Nothing was sent."
  end
  -- Pick only after every permission, buff, and rate-limit preflight passes.
  local message=self:Pick(category)
  if type(message)~="string" or #message==0 or #message>240 or
     message:find("[\r\n%%c]") then
    return false,"Invalid campfire story; nothing was sent."
  end
  -- MUST be called synchronously inside a hardware click handler, not a timer
  -- or OnUpdate: outdoor SAY messages are protected by the game.
  local ok,result=pcall(fn,message,"SAY")
  if not ok or result==false then
    return false,"WoW rejected the chat request. No retries were queued."
  end
  self.lastSent=now
  return true,message
end

function A:RefreshAvailability()
  if self.view and self.view.refresh then self.view.refresh() end
end

local driver=CreateFrame("Frame")
driver:RegisterEvent("PLAYER_ENTERING_WORLD")
driver:RegisterEvent("UNIT_AURA")
driver:SetScript("OnEvent",function(_,event,unit)
  if event=="UNIT_AURA" and unit~="player" then return end
  A:RefreshAvailability()
end)
